mapper.select:
SELECT sc.*
FROM edu_student_class sc
INNER JOIN edu_school_class c ON c.id = sc.class_id AND c.deleted = b'0'
INNER JOIN edu_school_year y ON y.id = c.school_year_id AND y.deleted = b'0'
WHERE sc.deleted = b'0'
  AND sc.student_id IN

    #{studentId}

  AND y.year_start = #{yearStart}
  AND y.year_end = #{yearEnd}
ORDER BY sc.student_id ASC, sc.start_date ASC, sc.id ASC

SELECT sc.* FROM edu_student_class sc INNER JOIN edu_school_class c ON c.id = sc.class_id AND c.deleted = b'0' INNER JOIN edu_school_year y ON y.id = c.school_year_id AND y.deleted = b'0' WHERE sc.deleted = b'0' AND sc.student_id IN
#{studentId}
AND y.year_catalog_id = #{yearCatalogId} ORDER BY sc.student_id ASC, sc.start_date ASC, sc.id ASC

SELECT sc.*
FROM edu_student_class sc
INNER JOIN edu_school_class c ON c.id = sc.class_id AND c.deleted = b'0'
INNER JOIN edu_school_year y ON y.id = c.school_year_id AND y.deleted = b'0'
WHERE sc.deleted = b'0'
  AND sc.student_id > #{startExclusiveStudentId}
  AND sc.student_id <= #{endInclusiveStudentId}
  AND y.year_start = #{yearStart}
  AND y.year_end = #{yearEnd}
ORDER BY sc.student_id ASC, sc.start_date ASC, sc.id ASC

